-- Branch-level isolation, layered on top of the school policies.
--
-- Branch A's rows stay in Branch A: Branch B cannot read them and cannot write
-- into them, even if an application query forgets its branch filter.
--
-- Three deliberate carve-outs, all required by the product rules:
--   * branch_id IS NULL  -> school-wide rows (notices, shared config) stay
--     visible to every branch. 175 of these 177 tables allow NULL.
--   * empty app.current_branch_ids -> no branch restriction. Set for a
--     school-level (main branch) admin, who manages all branches, and for a
--     PARENT, whose children may be enrolled in different branches.
--   * app.bypass_rls -> login / onboarding / seeds, which run before a tenant
--     is known.
--
-- RLS is the ENTITLEMENT boundary; the app still narrows to the active branch
-- via getEffectiveBranchId. Idempotent: safe to re-run.

DROP POLICY IF EXISTS tenant_isolation ON "AcademicPerformance";
CREATE POLICY tenant_isolation ON "AcademicPerformance" USING ((school_id = current_setting('app.current_school_id', true) AND (branch_id IS NULL OR coalesce(current_setting('app.current_branch_ids', true), '') = '' OR branch_id = ANY(string_to_array(current_setting('app.current_branch_ids', true), ',')))) OR coalesce(current_setting('app.bypass_rls', true), '') = 'on') WITH CHECK ((school_id = current_setting('app.current_school_id', true) AND (branch_id IS NULL OR coalesce(current_setting('app.current_branch_ids', true), '') = '' OR branch_id = ANY(string_to_array(current_setting('app.current_branch_ids', true), ',')))) OR coalesce(current_setting('app.bypass_rls', true), '') = 'on');

